import {closeDialog} from './ui-motion.js';
import {fallbackTrivia} from './trivia-fallback.js';
import {dailyQuestions,validTrivia,loadTrivia} from './trivia-loader.js';
let catalog=fallbackTrivia;export const trivia=fallbackTrivia.map(q=>[q.question,q.options,q.answer,q.explanation,'✦',q.source,q.id]);
let ready=loadTrivia().then(items=>{catalog=items;});
window.addEventListener('lab:quiz-updated',()=>{ready=loadTrivia().then(items=>{catalog=items;});});
const dialog=document.createElement('dialog');dialog.id='quick-quiz';dialog.setAttribute('aria-labelledby','quick-question');
dialog.innerHTML='<div class="quiz-header"><span>겨울밤의 지식 연구소</span><button class="icon-button" aria-label="퀴즈 닫기"><svg viewBox="0 0 24 24"><path d="m7 7 10 10M17 7 7 17"/></svg></button></div><h2 id="quick-question"></h2><div class="quiz-options"></div><div class="quiz-result" role="status" hidden></div><div class="quiz-footer"><span class="quiz-count"></span><button class="quiz-next" hidden>다음 <svg viewBox="0 0 24 24"><path d="M5 12h14m-5-5 5 5-5 5"/></svg></button></div><div class="quiz-burst" aria-hidden="true"></div>';
document.body.append(dialog);let order=[],index=0,score=0,answered=false,cleanup;
function fireworks(){const el=dialog.querySelector('.quiz-burst');el.replaceChildren();if(matchMedia('(prefers-reduced-motion: reduce)').matches||document.body.classList.contains('still'))return;const colors=['#ffcef0','#b9fff0','#f7e1a4','#d3c7ff'];for(let burst=0;burst<3;burst++)for(let i=0;i<24;i++){const p=document.createElement('i'),a=i/24*Math.PI*2,d=70+(i%4)*18;p.style.left=(burst===0?50:burst===1?18:82)+'%';p.style.top=(burst===0?30:48)+'%';p.style.animationDelay=burst*.14+'s';p.style.setProperty('--spark',colors[i%4]);p.style.setProperty('--sx',Math.cos(a)*d+'px');p.style.setProperty('--sy',Math.sin(a)*d+'px');el.append(p);}clearTimeout(cleanup);cleanup=setTimeout(()=>el.replaceChildren(),1900);}
function render(){answered=false;const [question,options,, ,symbol]=trivia[order[index]];dialog.querySelector('#quick-question').textContent=question;const choices=dialog.querySelector('.quiz-options');choices.replaceChildren();options.forEach((text,i)=>{const b=document.createElement('button');b.textContent=text;b.onclick=()=>answer(i);choices.append(b);});dialog.querySelector('.quiz-result').hidden=true;dialog.querySelector('.quiz-next').hidden=true;dialog.querySelector('.quiz-count').textContent=`${index+1} / ${order.length} · ${score} 정답`;}
function answer(choice){if(answered)return;answered=true;const [,,correct,explanation]=trivia[order[index]],ok=choice===correct;if(ok)score++;[...dialog.querySelector('.quiz-options').children].forEach((b,i)=>{b.disabled=true;b.classList.toggle('correct',i===correct);b.classList.toggle('wrong',i===choice&&!ok);});const result=dialog.querySelector('.quiz-result'),title=document.createElement('strong');title.textContent=ok?'정답!':'오답';result.replaceChildren(title,document.createTextNode(explanation));const source=trivia[order[index]][5];if(source){const link=document.createElement('a');link.className='quiz-source';link.textContent=source.title+' ↗';link.href=source.url;link.target='_blank';link.rel='noreferrer';result.append(link);const more=document.createElement('button');more.textContent='더 알아보기';more.onclick=()=>window.explainQuiz?.(trivia[order[index]][6],result);result.append(more);}result.hidden=false;dialog.querySelector('.quiz-next').hidden=false;dialog.querySelector('.quiz-next').textContent=index===order.length-1?'한 번 더 ↗':'다음 →';dialog.querySelector('.quiz-count').textContent=`${index+1} / ${order.length} · ${score} 정답`;window.labSound?.(ok?'correct':'wrong');window.dispatchEvent(new CustomEvent('lab:vfx',{detail:{kind:ok?'correct':'wrong',strength:.8}}));dialog.classList.remove('quiz-correct','quiz-wrong');dialog.classList.add(ok?'quiz-correct':'quiz-wrong');if(ok)fireworks();}
function reset(){const questions=dailyQuestions(catalog);trivia.splice(0,trivia.length,...questions.map(q=>[q.question,q.options,q.answer,q.explanation,'✦',q.source,q.id]));order=trivia.map((_,i)=>i);index=score=0;render();}
window.openQuickQuiz=async()=>{if(!dialog.open)dialog.showModal();document.body.classList.add('quiz-open');window.dispatchEvent(new Event('lab:pause'));dialog.querySelector('#quick-question').textContent='문제 불러오는 중…';await ready;if(!dialog.open)return;reset();window.labSound?.('quiz');};
dialog.querySelector('.icon-button').onclick=()=>closeDialog(dialog);dialog.querySelector('.quiz-next').onclick=()=>{if(++index===order.length)reset();else render();};dialog.addEventListener('close',()=>{clearTimeout(cleanup);dialog.querySelector('.quiz-burst').replaceChildren();document.body.classList.remove('quiz-open');window.dispatchEvent(new Event('lab:close'));});
document.querySelector('#go-quiz').onclick=()=>{document.querySelector('#park-menu').open=false;window.travelToPlace?.('quiz');};

dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog(dialog);});
